   148  /**
   149   * Return 1 if (x, y) lies in (the interior or boundary of) the image of the
   150   * HEALPix projection (in case proj=0) or in the image the rHEALPix projection
   151   * (in case proj=1), and return 0 otherwise.
   152   * @param north_square the position of the north polar square (rHEALPix only)
   153   * @param south_square the position of the south polar square (rHEALPix only)
   154   **/
   155  static int in_image(double x, double y, int proj, int north_square,
   156                      int south_square) {
   157      if (proj == 0) {
   158          double healpixVertsJit[][2] = {
   159              {-M_PI - EPS,  M_FORTPI},
   160              {-3*M_FORTPI,  M_HALFPI + EPS},
   161              {-M_HALFPI,    M_FORTPI + EPS},
   162              {-M_FORTPI,    M_HALFPI + EPS},
   163              {0.0,          M_FORTPI + EPS},
   164              {M_FORTPI,     M_HALFPI + EPS},
   165              {M_HALFPI,     M_FORTPI + EPS},
   166              {3*M_FORTPI,   M_HALFPI + EPS},
   167              {M_PI + EPS,   M_FORTPI},
   168              {M_PI + EPS,  -M_FORTPI},
   169              {3*M_FORTPI,  -M_HALFPI - EPS},
   170              {M_HALFPI,    -M_FORTPI - EPS},
   171              {M_FORTPI,    -M_HALFPI - EPS},
   172              {0.0,         -M_FORTPI - EPS},
   173              {-M_FORTPI,   -M_HALFPI - EPS},
   174              {-M_HALFPI,   -M_FORTPI - EPS},
   175              {-3*M_FORTPI, -M_HALFPI - EPS},
   176              {-M_PI - EPS, -M_FORTPI}
   177          };
   178          return pnpoly((int)sizeof(healpixVertsJit)/
   179                        sizeof(healpixVertsJit[0]), healpixVertsJit, x, y);
   180      } else {
   181          /**
   182           * Assigning each element by index to avoid warnings such as
   183           * 'initializer element is not computable at load time'.
   184           * Before C99 this was not allowed and to keep as portable as
   185           * possible we do it the C89 way here.
   186           * We need to assign the array this way because the input is
   187           * dynamic (north_square and south_square vars are unknown at
   188           * compile time).
   189           **/
   190          double rhealpixVertsJit[12][2];
   191          rhealpixVertsJit[0][0]  = -M_PI - EPS;
   192          rhealpixVertsJit[0][1]  =  M_FORTPI + EPS;
   193          rhealpixVertsJit[1][0]  = -M_PI + north_square*M_HALFPI- EPS;
   194          rhealpixVertsJit[1][1]  =  M_FORTPI + EPS;
   195          rhealpixVertsJit[2][0]  = -M_PI + north_square*M_HALFPI- EPS;
   196          rhealpixVertsJit[2][1]  =  3*M_FORTPI + EPS;
   197          rhealpixVertsJit[3][0]  = -M_PI + (north_square + 1.0)*M_HALFPI + EPS;
   198          rhealpixVertsJit[3][1]  =  3*M_FORTPI + EPS;
   199          rhealpixVertsJit[4][0]  = -M_PI + (north_square + 1.0)*M_HALFPI + EPS;
   200          rhealpixVertsJit[4][1]  =  M_FORTPI + EPS;
   201          rhealpixVertsJit[5][0]  =  M_PI + EPS;
   202          rhealpixVertsJit[5][1]  =  M_FORTPI + EPS;
   203          rhealpixVertsJit[6][0]  =  M_PI + EPS;
   204          rhealpixVertsJit[6][1]  = -M_FORTPI - EPS;
   205          rhealpixVertsJit[7][0]  = -M_PI + (south_square + 1.0)*M_HALFPI + EPS;
   206          rhealpixVertsJit[7][1]  = -M_FORTPI - EPS;
   207          rhealpixVertsJit[8][0]  = -M_PI + (south_square + 1.0)*M_HALFPI + EPS;
   208          rhealpixVertsJit[8][1]  = -3*M_FORTPI - EPS;
   209          rhealpixVertsJit[9][0]  = -M_PI + south_square*M_HALFPI - EPS;
   210          rhealpixVertsJit[9][1]  = -3*M_FORTPI - EPS;
   211          rhealpixVertsJit[10][0] = -M_PI + south_square*M_HALFPI - EPS;
   212          rhealpixVertsJit[10][1] = -M_FORTPI - EPS;
   213          rhealpixVertsJit[11][0] = -M_PI - EPS;
   214          rhealpixVertsJit[11][1] = -M_FORTPI - EPS;
   215
   216          return pnpoly((int)sizeof(rhealpixVertsJit)/
   217                        sizeof(rhealpixVertsJit[0]), rhealpixVertsJit, x, y);
   218      }
   219  }
