   222  /**
   223   * Return the authalic latitude of latitude alpha (if inverse=0) or
   224   * return the approximate latitude of authalic latitude alpha (if inverse=1).
   225   * P contains the relevant ellipsoid parameters.
   226   **/
   227  static double auth_lat(PJ *P, double alpha, int inverse) {
   228      struct pj_opaque *Q = P->opaque;
   229      if (inverse == 0) {
   230          /* Authalic latitude. */
   231          double q = pj_qsfn(sin(alpha), P->e, 1.0 - P->es);
   232          double qp = Q->qp;
   233          double ratio = q/qp;
   234
   235          if (fabs(ratio) > 1) {
   236              /* Rounding error. */
   237              ratio = pj_sign(ratio);
   238          }
   239          return asin(ratio);
   240      } else {
   241          /* Approximation to inverse authalic latitude. */
   242          return pj_authlat(alpha, Q->apa);
   243      }
   244  }
