   247  /**
   248   * Return the HEALPix projection of the longitude-latitude point lp on
   249   * the unit sphere.
   250  **/
   251  static XY healpix_sphere(LP lp) {
   252      double lam = lp.lam;
   253      double phi = lp.phi;
   254      double phi0 = asin(2.0/3.0);
   255      XY xy;
   256
   257      /* equatorial region */
   258      if ( fabs(phi) <= phi0) {
   259          xy.x = lam;
   260          xy.y = 3*M_PI/8*sin(phi);
   261      } else {
   262          double lamc;
   263          double sigma = sqrt(3*(1 - fabs(sin(phi))));
   264          double cn = floor(2*lam / M_PI + 2);
   265          if (cn >= 4) {
   266              cn = 3;
   267          }
   268          lamc = -3*M_FORTPI + M_HALFPI*cn;
   269          xy.x = lamc + (lam - lamc)*sigma;
   270          xy.y = pj_sign(phi)*M_FORTPI*(2 - sigma);
   271      }
   272      return xy;
   273  }
