   276  /**
   277   * Return the inverse of healpix_sphere().
   278  **/
   279  static LP healpix_sphere_inverse(XY xy) {
   280      LP lp;
   281      double x = xy.x;
   282      double y = xy.y;
   283      double y0 = M_FORTPI;
   284
   285      /* Equatorial region. */
   286      if (fabs(y) <= y0) {
   287          lp.lam = x;
   288          lp.phi = asin(8*y/(3*M_PI));
   289      } else if (fabs(y) < M_HALFPI) {
   290          double cn = floor(2*x/M_PI + 2);
   291          double xc, tau;
   292          if (cn >= 4) {
   293              cn = 3;
   294          }
   295          xc = -3*M_FORTPI + M_HALFPI*cn;
   296          tau = 2.0 - 4*fabs(y)/M_PI;
   297          lp.lam = xc + (x - xc)/tau;
   298          lp.phi = pj_sign(y)*asin(1.0 - pow(tau, 2)/3.0);
   299      } else {
   300          lp.lam = -M_PI;
   301          lp.phi = pj_sign(y)*M_HALFPI;
   302      }
   303      return (lp);
   304  }
