   348  /**
   349   * Return the number of the polar cap, the pole point coordinates, and
   350   * the region that (x, y) lies in.
   351   * If inverse=0, then assume (x,y) lies in the image of the HEALPix
   352   * projection of the unit sphere.
   353   * If inverse=1, then assume (x,y) lies in the image of the
   354   * (north_square, south_square)-rHEALPix projection of the unit sphere.
   355   **/
   356  static CapMap get_cap(double x, double y, int north_square, int south_square,
   357                        int inverse) {
   358      CapMap capmap;
   359      double c;
   360
   361      capmap.x = x;
   362      capmap.y = y;
   363      if (inverse == 0) {
   364          if (y > M_FORTPI) {
   365              capmap.region = north;
   366              c = M_HALFPI;
   367          } else if (y < -M_FORTPI) {
   368              capmap.region = south;
   369              c = -M_HALFPI;
   370          } else {
   371              capmap.region = equatorial;
   372              capmap.cn = 0;
   373              return capmap;
   374          }
   375          /* polar region */
   376          if (x < -M_HALFPI) {
   377              capmap.cn = 0;
   378              capmap.x = (-3*M_FORTPI);
   379              capmap.y = c;
   380          } else if (x >= -M_HALFPI && x < 0) {
   381              capmap.cn = 1;
   382              capmap.x = -M_FORTPI;
   383              capmap.y = c;
   384          } else if (x >= 0 && x < M_HALFPI) {
   385              capmap.cn = 2;
   386              capmap.x = M_FORTPI;
   387              capmap.y = c;
   388          } else {
   389              capmap.cn = 3;
   390              capmap.x = 3*M_FORTPI;
   391              capmap.y = c;
   392          }
   393      } else {
   394          if (y > M_FORTPI) {
   395              capmap.region = north;
   396              capmap.x = -3*M_FORTPI + north_square*M_HALFPI;
   397              capmap.y = M_HALFPI;
   398              x = x - north_square*M_HALFPI;
   399          } else if (y < -M_FORTPI) {
   400              capmap.region = south;
   401              capmap.x = -3*M_FORTPI + south_square*M_HALFPI;
   402              capmap.y = -M_HALFPI;
   403              x = x - south_square*M_HALFPI;
   404          } else {
   405              capmap.region = equatorial;
   406              capmap.cn = 0;
   407              return capmap;
   408          }
   409          /* Polar Region, find the HEALPix polar cap number that
   410             x, y moves to when rHEALPix polar square is disassembled. */
   411          if (capmap.region == north) {
   412              if (y >= -x - M_FORTPI - EPS && y < x + 5*M_FORTPI - EPS) {
   413                  capmap.cn = (north_square + 1) % 4;
   414              } else if (y > -x -M_FORTPI + EPS && y >= x + 5*M_FORTPI - EPS) {
   415                  capmap.cn = (north_square + 2) % 4;
   416              } else if (y <= -x -M_FORTPI + EPS && y > x + 5*M_FORTPI + EPS) {
   417                  capmap.cn = (north_square + 3) % 4;
   418              } else {
   419                  capmap.cn = north_square;
   420              }
   421          } else if (capmap.region == south) {
   422              if (y <= x + M_FORTPI + EPS && y > -x - 5*M_FORTPI + EPS) {
   423                  capmap.cn = (south_square + 1) % 4;
   424              } else if (y < x + M_FORTPI - EPS && y <= -x - 5*M_FORTPI + EPS) {
   425                  capmap.cn = (south_square + 2) % 4;
   426              } else if (y >= x + M_FORTPI - EPS && y < -x - 5*M_FORTPI - EPS) {
   427                  capmap.cn = (south_square + 3) % 4;
   428              } else {
   429                  capmap.cn = south_square;
   430              }
   431          }
   432      }
   433      return capmap;
   434  }
