   521  static LP s_healpix_inverse(XY xy, PJ *P) { /* sphere */
   522      /* Check whether (x, y) lies in the HEALPix image */
   523      if (in_image(xy.x, xy.y, 0, 0, 0) == 0) {
   524          LP lp;
   525          lp.lam = HUGE_VAL;
   526          lp.phi = HUGE_VAL;
