   534  static LP e_healpix_inverse(XY xy, PJ *P) { /* ellipsoid */
   535      LP lp = {0.0,0.0};
   536
   537      /* Check whether (x, y) lies in the HEALPix image. */
   538      if (in_image(xy.x, xy.y, 0, 0, 0) == 0) {
