   601  static void *freeup_new (PJ *P) {                       /* Destructor */
   602      if (0==P)
   603          return 0;
   604      if (0==P->opaque)
   605          return pj_dealloc (P);
   606
   607      if (P->opaque->apa)
   608          pj_dealloc(P->opaque->apa);
   609
   610      pj_dealloc (P->opaque);
   611      return pj_dealloc(P);
   612  }
