   620  PJ *PROJECTION(healpix) {
   621      struct pj_opaque *Q = pj_calloc (1, sizeof (struct pj_opaque));
   622      if (0==Q)
   623          return freeup_new (P);
   624      P->opaque = Q;
   625
   626      if (P->es != 0.0) {
   627          Q->apa = pj_authset(P->es);             /* For auth_lat(). */
   628          Q->qp = pj_qsfn(1.0, P->e, P->one_es);  /* For auth_lat(). */
   629          P->a = P->a*sqrt(0.5*Q->qp);            /* Set P->a to authalic radius. */
   630          P->ra = 1.0/P->a;
   631          P->fwd = e_healpix_forward;
   632          P->inv = e_healpix_inverse;
   633      } else {
   634          P->fwd = s_healpix_forward;
   635          P->inv = s_healpix_inverse;
   636      }
   637
   638      return P;
   639  }
