   642  PJ *PROJECTION(rhealpix) {
   643      struct pj_opaque *Q = pj_calloc (1, sizeof (struct pj_opaque));
   644      if (0==Q)
   645          return freeup_new (P);
   646      P->opaque = Q;
   647
   648      Q->north_square = pj_param(P->ctx, P->params,"inorth_square").i;
   649      Q->south_square = pj_param(P->ctx, P->params,"isouth_square").i;
   650
   651      /* Check for valid north_square and south_square inputs. */
   652      if (Q->north_square < 0 || Q->north_square > 3) {
   653          proj_errno_set(P, PJD_ERR_AXIS);
   654          return freeup_new(P);
   655      }
   656      if (Q->south_square < 0 || Q->south_square > 3) {
   657          proj_errno_set(P, PJD_ERR_AXIS);
   658          return freeup_new(P);
   659      }
   660      if (P->es != 0.0) {
   661          Q->apa = pj_authset(P->es); /* For auth_lat(). */
   662          Q->qp = pj_qsfn(1.0, P->e, P->one_es); /* For auth_lat(). */
   663          P->a = P->a*sqrt(0.5*Q->qp); /* Set P->a to authalic radius. */
   664          P->ra = 1.0/P->a;
   665          P->fwd = e_rhealpix_forward;
   666          P->inv = e_rhealpix_inverse;
   667      } else {
   668          P->fwd = s_rhealpix_forward;
   669          P->inv = s_rhealpix_inverse;
   670      }
   671
   672      return P;
